import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int[] a = new int[6];
        int sum = 0;
        for (int i = 0; i < 6; i++) {
            a[i] = sc.nextInt();
            sum += a[i];
        }

        if (sum % 3 != 0) {
            System.out.println("N");
            return;
        }

        int target = sum / 3;
        boolean possible = false;

        for (int i = 0; i < 6; i++) {
            if (a[i] == target) {
                for (int j = 0; j < 6; j++) {
                    if (j == i) continue;
                    for (int k = j + 1; k < 6; k++) {
                        if (k == i) continue;
                        if (a[j] + a[k] == target) {
                            possible = true;
                            break;
                        }
                    }
                    if (possible) break;
                }
            }
            if (possible) break;
        }

        if (possible) {
            System.out.println("S");
        } else {
            System.out.println("N");
        }
    }
}
